-- 0012_seed_80_day_plan_v2.sql
--
-- The Strategic Study Calendar's sequencing, at full syllabus coverage.
--
-- Supersedes both earlier defaults. 80 days, 283 slots, all 243 microthemes.
--
-- How it is built
-- ---------------
-- Days 1-74 are the 75-day calendar's own days, in its order and grouping, with
-- the 70 microthemes it left out woven into whichever of those days already
-- covers their subject -- 67 of the 70 landed in their own thematic block, at
-- most four topics to a day. Day 75 carries the three that did not fit
-- (Communication Infrastructure, Rural Development & Panchayati Raj, and the
-- State Finance Commission -- all Economy of Rajasthan, whose block was full).
-- Days 76-79 are one revision day per block, and day 80 is the OMR simulation,
-- sampling one subject from each of four.
--
-- Mapping was done on microtheme NAME, not the calendar's M-codes. The two
-- numberings disagree in nineteen places: M144 is labelled "Governor of
-- Rajasthan" in the calendar while m144 here is the Central Vigilance
-- Commission. Trusting the codes would have scheduled the wrong topic on
-- roughly one day in four through the polity blocks.
--
-- The calendar's nine consolidation days carry no microthemes of their own.
-- isDayClearedFor returns false for a day with an empty topic list, so such a
-- day can never be cleared and would stall a student permanently. Each now
-- repeats the highest-tier microthemes of the block it reviews; clearing is
-- tracked per (day, topic), so a repeat is a real second pass.
--
-- Run after 0011. Re-running bumps the version and replaces the days.

update public.plan_templates set is_default = false where is_default and owner_id is null;

insert into public.plan_templates (id, name, blurb, scope, days, is_default, version, owner_id)
