on conflict (id) do update
  set name    = excluded.name,
      blurb   = excluded.blurb,
      scope   = excluded.scope,
      days    = excluded.days,
      is_default = true,
      version = public.plan_templates.version + 1,
      updated_at = now();

-- Sanity: 80 days, 283 slots, no empty day, 243 distinct microthemes.
do $$
declare d int; s int; empt int; distinct_t int;
begin
  select jsonb_array_length(days) into d from public.plan_templates where id = 'ras-80-day-v2';
  select count(*), count(distinct slot->>'topicId') into s, distinct_t
    from public.plan_templates t,
         lateral jsonb_array_elements(t.days) day,
         lateral jsonb_array_elements(day) slot
   where t.id = 'ras-80-day-v2';
  select count(*) into empt
    from public.plan_templates t,
         lateral jsonb_array_elements(t.days) day
   where t.id = 'ras-80-day-v2' and jsonb_array_length(day) = 0;
  if d <> 80 or s <> 283 or empt <> 0 or distinct_t <> 243 then
    raise exception 'plan is % days / % slots / % empty / % microthemes, expected 80 / 283 / 0 / 243',
      d, s, empt, distinct_t;
  end if;
end $$;
